#!/usr/bin/env bash
# Self-contained CSS для analytics/bg2-page-round (prod parity ★ BG-2, bash-only).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BOARD="$(cd "$ROUND/../../board-game" && pwd)"
OUT="$ROUND/lab-base.css"
SOURCES=(
  "$BOARD/styles.css"
  "$BOARD/logic-round/styles.css"
  "$BOARD/hybrid-round/styles.css"
  "$BOARD/screens-round/styles.css"
)

{
  cat <<'HDR'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: analytics/bg2-page-round */
/* Sources: board-game/styles.css (tokens ADR-014) + logic-round + hybrid-round + screens-round (экран «Аналитика» ★ BG-2) */

HDR
  for src in "${SOURCES[@]}"; do
    if [[ ! -f "$src" ]]; then
      echo "sync-lab.sh: missing source: $src" >&2
      exit 1
    fi
    cat "$src"
    printf '\n'
  done
} > "$OUT"

cp "$BOARD/screens-round/assets/monetka-mascot.png" "$ROUND/assets/monetka-mascot.png"
echo "OK: $OUT"
